<template>
  <div class="privacyOperationsPage">
    <cruioHeader />
    <main class="pageContent">
      <header class="pageHeading"><div><p class="eyebrow">岗位工作台</p><h1>隐私申请处理</h1><p>仅在当前授权范围内查看申请；对象处理结果以服务端核验为准。</p></div><button class="secondaryButton" type="button" :disabled="loading" @click="loadRequests()">刷新队列</button></header>
      <p v-if="errorMessage" class="feedback error" role="alert">{{ errorMessage }}</p><p v-if="successMessage" class="feedback success" role="status">{{ successMessage }}</p>
      <div class="contentGrid">
        <section class="panel requestList" aria-labelledby="listHeading"><header class="sectionHeading"><h2 id="listHeading">授权范围内的申请</h2></header><div class="filters"><label>类别<select v-model="filterCategory" @change="loadRequests()"><option value="">全部</option><option v-for="item in categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>状态<select v-model="filterStatus" @change="loadRequests()"><option value="">全部</option><option v-for="item in statuses" :key="item.value" :value="item.value">{{ item.label }}</option></select></label></div><p v-if="loading && !requests.length" class="emptyState">正在读取队列…</p><p v-else-if="!requests.length" class="emptyState">当前岗位范围内暂无申请。</p><button v-for="item in requests" :key="item.id" class="requestRow" :class="{ selected: selectedRequest?.id === item.id }" type="button" @click="openRequest(item.id)"><span><strong>{{ item.subject }}</strong><span class="statusBadge">{{ statusLabel(item.status) }}</span></span><small>{{ item.number }} · {{ categoryLabel(item.category) }} · {{ item.ownerId }} · {{ formatDate(item.updatedAt) }}</small></button><button v-if="nextCursor" class="secondaryButton loadMore" type="button" :disabled="loadingMore" @click="loadRequests(false)">{{ loadingMore ? "正在加载…" : "加载更多" }}</button></section>
        <section v-if="selectedRequest" class="panel requestDetail" aria-labelledby="detailHeading"><header class="sectionHeading"><div><p class="eyebrow">{{ selectedRequest.number }} · {{ categoryLabel(selectedRequest.category) }}</p><h2 id="detailHeading">{{ selectedRequest.subject }}</h2><p>申请人 {{ selectedRequest.ownerId }} · {{ statusLabel(selectedRequest.status) }}</p></div></header><p class="description">{{ selectedRequest.description }}</p>
          <article v-for="object in objects" :key="object.id" class="objectCard"><header><div><h3>{{ objectTypeLabel(object.objectType) }}</h3><p class="objectId">{{ object.sourceId || "本人账户" }}</p></div><span class="statusBadge">{{ objectStatusLabel(object.status) }}</span></header><p>申请动作：{{ categoryLabel(object.requestedAction) }}</p><p v-if="object.userReason" class="userReason">用户可见说明：{{ object.userReason }}</p><details class="internalEvidence"><summary>内部核查材料</summary><p v-if="object.internalReason">内部备注：{{ object.internalReason }}</p><p v-if="object.evidenceRef">证据引用：<a :href="object.evidenceRef" target="_blank" rel="noopener noreferrer">{{ object.evidenceRef }}</a></p><p v-if="!object.internalReason && !object.evidenceRef">暂无内部备注或证据引用。</p></details>
            <div class="objectEditor"><label>对象处理状态<select v-model="objectEdits[object.id].status"><option v-for="item in objectStatuses" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>用户可见说明<textarea v-model.trim="objectEdits[object.id].userReason" maxlength="1000" rows="2" /></label><label>内部核查备注<textarea v-model.trim="objectEdits[object.id].internalReason" maxlength="2000" rows="2" /></label><label>证据引用 URL<input v-model.trim="objectEdits[object.id].evidenceRef" type="url" maxlength="1000" /></label><label>原因类型<select v-model="objectEdits[object.id].reasonCode"><option value="">无</option><option v-for="item in reasonCodes" :key="item.value" :value="item.value">{{ item.label }}</option></select></label></div>
          </article>
          <section class="timelinePanel"><h3>申请时间线</h3><ol class="timeline"><li v-for="event in timeline" :key="event.id"><strong>{{ event.eventType === "userSupplement" ? "用户补充" : event.actorRole === "operator" ? "岗位处理" : "申请更新" }}</strong><p>{{ event.details?.message || event.details?.userMessage || event.details?.internalNote || "申请记录已更新。" }}</p><time>{{ formatDate(event.createdAt) }}</time></li></ol><p v-if="!timeline.length" class="emptyState">暂无时间线记录。</p></section>
          <form class="requestAction" @submit.prevent="prepareAction"><label>申请状态<select v-model="requestStatus"><option v-for="item in statuses" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>用户可见回复<textarea v-model.trim="userMessage" maxlength="2000" rows="3" /></label><label>内部备注<textarea v-model.trim="internalNote" maxlength="3000" rows="3" /></label><button class="primaryButton" type="submit" :disabled="saving || !hasChanges">核对并保存处理结果</button></form>
        </section>
      </div>
      <div v-if="showConfirm" class="modalBackdrop" @click.self="closeConfirm"><section ref="confirmDialog" class="confirmDialog" role="dialog" aria-modal="true" aria-labelledby="confirmHeading" tabindex="-1" @keydown="trapFocus" @keydown.esc.prevent.stop="closeConfirm"><h2 id="confirmHeading">确认处理隐私申请</h2><p>请核对申请、每个对象的新状态与用户可见说明。服务端会检查申请版本和事实，不会执行永久删除或假称外部状态已改变。</p><ul class="confirmList"><li v-for="object in changedObjects" :key="object.id">{{ objectTypeLabel(object.objectType) }} {{ object.sourceId || "本人账户" }}：{{ objectStatusLabel(objectEdits[object.id].status) }}<span v-if="objectEdits[object.id].userReason">；{{ objectEdits[object.id].userReason }}</span></li></ul><p>申请状态：{{ statusLabel(requestStatus) }}</p><label>当前密码<input ref="passwordInput" v-model="currentPassword" type="password" autocomplete="current-password" required minlength="8" maxlength="256" :disabled="saving" /></label><p v-if="dialogError" class="feedback error" role="alert">{{ dialogError }}</p><div class="dialogActions"><button class="secondaryButton" type="button" :disabled="saving" @click="closeConfirm">返回修改</button><button class="primaryButton" type="button" :disabled="saving || !currentPassword" @click="saveAction">{{ saving ? "正在保存…" : "确认保存" }}</button></div></section></div>
    </main>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import cruioHeader from "@/components/cruioHeader.vue";
import { api } from "@/lib/cruioApi";
import { useCruioSession } from "@/stores/cruioSession";

type Summary = { id: string; number: string; ownerId: string; category: string; status: string; subject: string; createdAt: string; updatedAt: string };
type PrivacyObject = { id: string; sourceId: string | null; objectType: string; requestedAction: string; status: string; reasonCode: string | null; userReason: string | null; internalReason: string | null; evidenceRef: string | null };
type PrivacyEvent = { id: string; actorRole: string; eventType: string; details: Record<string, string>; createdAt: string };
type Detail = Summary & { description: string };
type Edit = { status: string; reasonCode: string; userReason: string; internalReason: string; evidenceRef: string };
const categories = [{ value: "access", label: "访问" }, { value: "copy", label: "获取副本" }, { value: "correction", label: "更正" }, { value: "supplement", label: "补充" }, { value: "deletion", label: "删除" }, { value: "restriction", label: "限制处理" }, { value: "explanation", label: "处理说明" }, { value: "accountClosure", label: "关闭账户" }];
const statuses = [{ value: "received", label: "已收到" }, { value: "identityReview", label: "身份核验" }, { value: "awaitingUser", label: "等待用户补充" }, { value: "processing", label: "处理中" }, { value: "partiallyCompleted", label: "部分完成" }, { value: "completed", label: "已完成" }, { value: "partiallyRefused", label: "部分未受理" }, { value: "appealReview", label: "复核中" }, { value: "closed", label: "已结束" }];
const objectStatuses = [{ value: "pending", label: "待处理" }, { value: "processing", label: "处理中" }, { value: "awaitingUser", label: "等待用户补充" }, { value: "partial", label: "部分完成" }, { value: "completed", label: "已完成" }, { value: "restricted", label: "已限制" }, { value: "softDeleted", label: "已软删除" }, { value: "retained", label: "继续保留" }, { value: "refused", label: "未受理" }];
const reasonCodes = [{ value: "outsideImplementedScope", label: "当前范围未接入" }, { value: "sourceFactProtection", label: "保留来源事实" }, { value: "externalStateUnverified", label: "外部状态未核实" }, { value: "needsUserDetail", label: "需要用户补充" }, { value: "retentionReview", label: "保留期限核查" }, { value: "other", label: "其他" }];
const route = useRoute(); const router = useRouter(); const session = useCruioSession();
const requests = ref<Summary[]>([]); const nextCursor = ref<{ updatedAt: string; id: string } | null>(null); const filterCategory = ref(""); const filterStatus = ref(""); const selectedRequest = ref<Detail | null>(null); const objects = ref<PrivacyObject[]>([]); const timeline = ref<PrivacyEvent[]>([]); const objectEdits = reactive<Record<string, Edit>>({}); const requestStatus = ref("received"); const userMessage = ref(""); const internalNote = ref("");
const loading = ref(true); const loadingMore = ref(false); const saving = ref(false); const showConfirm = ref(false); const currentPassword = ref(""); const dialogError = ref(""); const errorMessage = ref(""); const successMessage = ref(""); const confirmDialog = ref<HTMLElement | null>(null); const passwordInput = ref<HTMLInputElement | null>(null); const returnFocus = ref<HTMLElement | null>(null);
const changedObjects = computed(() => objects.value.filter(item => { const edit = objectEdits[item.id]; return edit && JSON.stringify(edit) !== JSON.stringify({ status: item.status, reasonCode: item.reasonCode ?? "", userReason: item.userReason ?? "", internalReason: item.internalReason ?? "", evidenceRef: item.evidenceRef ?? "" }); }));
const hasChanges = computed(() => changedObjects.value.length > 0 || requestStatus.value !== selectedRequest.value?.status || Boolean(userMessage.value.trim()) || Boolean(internalNote.value.trim()));
function categoryLabel(value: string) { return categories.find(item => item.value === value)?.label ?? "其他申请"; }
function objectTypeLabel(value: string) { return ({ account: "本人账户", asset: "素材", task: "生成任务", work: "作品", ledger: "积分账单", credential: "凭据记录", supportTicket: "客服工单", externalMapping: "外部映射" } as Record<string, string>)[value] ?? "申请对象"; }
function statusLabel(value: string) { return statuses.find(item => item.value === value)?.label ?? "处理中"; }
function objectStatusLabel(value: string) { return objectStatuses.find(item => item.value === value)?.label ?? "状态待确认"; }
function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString("zh-CN"); }
function isAuthorized() { return session.user?.roles?.some(role => role.role === "privacyOperator" && !role.revokedAt && new Date(role.expiresAt).getTime() > Date.now()) ?? false; }
async function loadRequests(reset = true) {
  if (reset) { nextCursor.value = null; selectedRequest.value = null; objects.value = []; timeline.value = []; } else loadingMore.value = true;
  errorMessage.value = ""; if (reset) loading.value = true;
  try { const params = new URLSearchParams({ limit: "30" }); if (filterCategory.value) params.set("category", filterCategory.value); if (filterStatus.value) params.set("status", filterStatus.value); if (!reset && nextCursor.value) { params.set("updatedAt", nextCursor.value.updatedAt); params.set("id", nextCursor.value.id); } const result = await api<{ requests: Summary[]; nextCursor: { updatedAt: string; id: string } | null }>(`/api/operations/privacy/requests?${params}`); requests.value = reset ? result.requests : [...requests.value, ...result.requests]; nextCursor.value = result.nextCursor; }
  catch (error) { errorMessage.value = error instanceof Error ? error.message : "隐私处理队列暂时无法读取。"; }
  finally { loading.value = false; loadingMore.value = false; }
}
async function openRequest(requestId: string) {
  errorMessage.value = "";
  try { const result = await api<{ request: Detail; objects: PrivacyObject[]; timeline: PrivacyEvent[] }>(`/api/operations/privacy/requests/${encodeURIComponent(requestId)}`); selectedRequest.value = result.request; objects.value = result.objects; timeline.value = result.timeline; requestStatus.value = result.request.status; userMessage.value = ""; internalNote.value = ""; for (const key of Object.keys(objectEdits)) delete objectEdits[key]; for (const item of result.objects) objectEdits[item.id] = { status: item.status, reasonCode: item.reasonCode ?? "", userReason: item.userReason ?? "", internalReason: item.internalReason ?? "", evidenceRef: item.evidenceRef ?? "" }; }
  catch (error) { errorMessage.value = error instanceof Error ? error.message : "申请不在当前岗位授权范围内。"; }
}
function prepareAction(event: SubmitEvent) { if (!selectedRequest.value || !hasChanges.value || saving.value) return; returnFocus.value = event.submitter instanceof HTMLElement ? event.submitter : document.activeElement instanceof HTMLElement ? document.activeElement : null; dialogError.value = ""; currentPassword.value = ""; showConfirm.value = true; void nextTick(() => passwordInput.value?.focus()); }
function closeConfirm() { if (saving.value) return; showConfirm.value = false; currentPassword.value = ""; dialogError.value = ""; void nextTick(() => returnFocus.value?.focus()); }
function trapFocus(event: KeyboardEvent) { if (event.key !== "Tab" || !confirmDialog.value) return; const focusable = [...confirmDialog.value.querySelectorAll<HTMLElement>("button:not(:disabled), input:not(:disabled), [href], [tabindex]:not([tabindex='-1'])")]; const first = focusable[0]; const last = focusable.at(-1); if (!first || !last) { event.preventDefault(); confirmDialog.value.focus(); } else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }
async function saveAction() {
  if (saving.value || !selectedRequest.value || !currentPassword.value) return; saving.value = true; dialogError.value = ""; errorMessage.value = ""; successMessage.value = "";
  const requestSnapshot = selectedRequest.value; const payload = { currentPassword: currentPassword.value, expectedUpdatedAt: requestSnapshot.updatedAt, idempotencyKey: crypto.randomUUID(), requestStatus: requestStatus.value, userMessage: userMessage.value.trim() || undefined, internalNote: internalNote.value.trim() || undefined, objectUpdates: changedObjects.value.map(item => ({ objectId: item.id, ...objectEdits[item.id], reasonCode: objectEdits[item.id].reasonCode || undefined, userReason: objectEdits[item.id].userReason.trim() || undefined, internalReason: objectEdits[item.id].internalReason.trim() || undefined, evidenceRef: objectEdits[item.id].evidenceRef.trim() || undefined })) };
  try { const result = await api<{ requestId: string; status: string; idempotent: boolean }>(`/api/operations/privacy/requests/${encodeURIComponent(requestSnapshot.id)}/actions`, { method: "POST", body: JSON.stringify(payload) }); if (result.requestId !== requestSnapshot.id) throw new Error("服务端返回的申请编号不匹配。"); currentPassword.value = ""; showConfirm.value = false; successMessage.value = `服务端已记录处理结果：${statusLabel(result.status)}。`; await loadRequests(); await openRequest(requestSnapshot.id); }
  catch (error) { dialogError.value = error instanceof Error ? error.message : "处理结果未能保存。"; }
  finally { saving.value = false; }
}
onMounted(async () => { const user = await session.initialize(); if (!user) { await router.replace({ path: "/login", query: { next: route.fullPath } }); return; } if (!isAuthorized()) { loading.value = false; errorMessage.value = "当前账号没有隐私运营岗位授权。管理员不会自动获得该权限。"; return; } await loadRequests(); const requestId = typeof route.query.requestId === "string" ? route.query.requestId : ""; if (requestId) await openRequest(requestId); });
</script>

<style scoped lang="scss">
.privacyOperationsPage { min-height: 100dvh; background: var(--cr-page-background); color: var(--cr-text-primary); }.pageContent { width: min(100% - 48px, 1280px); margin: 0 auto; padding: 24px 0; }.pageHeading, .sectionHeading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }.pageHeading { margin-bottom: 24px; h1 { margin: 0; font-size: 20px; line-height: 1.4; } p:not(.eyebrow) { margin: 8px 0 0; color: var(--cr-text-secondary); font-size: 14px; line-height: 1.5; } }.eyebrow { margin: 0 0 4px; color: var(--cr-text-muted); font-size: 12px; }.sectionHeading h2 { margin: 0; font-size: 16px; }.sectionHeading p { margin: 8px 0 0; color: var(--cr-text-secondary); font-size: 12px; }
.contentGrid { display: grid; grid-template-columns: minmax(280px, .7fr) minmax(0, 1.3fr); align-items: start; gap: 16px; }.panel { min-width: 0; padding: 16px; border: 1px solid var(--cr-border-subtle); border-radius: 8px; background: var(--cr-surface); }.sectionHeading { margin-bottom: 12px; }.filters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-bottom: 12px; }label { display: grid; gap: 8px; min-width: 0; color: var(--cr-text-secondary); font-size: 14px; }input, select, textarea { width: 100%; min-width: 0; padding: 8px 12px; border: 1px solid var(--cr-border-strong); border-radius: 6px; color: var(--cr-text-primary); background: var(--cr-surface); font: inherit; font-size: 14px; }textarea { resize: vertical; }input:focus-visible, select:focus-visible, textarea:focus-visible, button:focus-visible, summary:focus-visible { outline: 2px solid var(--cr-border-focus); outline-offset: 2px; }
.requestRow { display: grid; gap: 8px; width: 100%; margin-top: 8px; padding: 12px; border: 1px solid var(--cr-border-subtle); border-radius: 8px; color: var(--cr-text-primary); background: var(--cr-surface); text-align: left; cursor: pointer; }.requestRow:hover, .requestRow.selected { background: var(--cr-surface-hover); }.requestRow > span, .objectCard header { display: flex; align-items: center; justify-content: space-between; gap: 8px; }.requestRow strong { font-size: 14px; overflow-wrap: anywhere; }.requestRow small, .objectId { color: var(--cr-text-muted); font-size: 12px; overflow-wrap: anywhere; }.statusBadge { flex: 0 0 auto; padding: 4px 8px; border-radius: 6px; color: var(--cr-text-secondary); background: var(--cr-surface-subtle); font-size: 12px; }.loadMore { margin-top: 12px; }.requestDetail { display: grid; gap: 12px; }.requestDetail .sectionHeading { align-items: start; margin: 0; }.requestDetail h2 { overflow-wrap: anywhere; }.description { margin: 0; color: var(--cr-text-secondary); font-size: 14px; line-height: 1.5; white-space: pre-wrap; }.objectCard { display: grid; gap: 8px; min-width: 0; padding: 12px; border: 1px solid var(--cr-border-subtle); border-radius: 8px; }.objectCard h3, .timelinePanel h3 { margin: 0; font-size: 14px; }.objectCard header p { margin: 4px 0 0; }.objectCard > p { margin: 0; color: var(--cr-text-secondary); font-size: 14px; line-height: 1.5; overflow-wrap: anywhere; }.objectCard .userReason { color: var(--cr-text-primary); }.internalEvidence { color: var(--cr-text-secondary); font-size: 12px; }.internalEvidence summary { width: fit-content; cursor: pointer; }.internalEvidence p { margin: 8px 0 0; overflow-wrap: anywhere; }.internalEvidence a { color: var(--cr-brand-primary); }.objectEditor { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; padding-top: 12px; border-top: 1px solid var(--cr-border-subtle); }.objectEditor label:nth-child(2), .objectEditor label:nth-child(3) { grid-column: 1 / -1; }
.timelinePanel, .requestAction { display: grid; gap: 12px; padding-top: 12px; border-top: 1px solid var(--cr-border-subtle); }.timeline { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }.timeline li { display: grid; gap: 4px; padding: 12px; background: var(--cr-surface-subtle); border-left: 3px solid var(--cr-brand-primary); }.timeline strong { font-size: 14px; }.timeline p, .timeline time { margin: 0; color: var(--cr-text-muted); font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }.primaryButton, .secondaryButton { min-height: 36px; width: fit-content; padding: 8px 12px; border: 1px solid var(--cr-border-subtle); border-radius: 6px; color: var(--cr-text-primary); background: var(--cr-surface); font: inherit; font-size: 14px; cursor: pointer; }.primaryButton { border-color: transparent; background: var(--cr-gradient); font-weight: 600; }.primaryButton:disabled, .secondaryButton:disabled { opacity: .55; cursor: not-allowed; }.feedback { margin: 0 0 16px; font-size: 14px; }.feedback.error { color: var(--cr-status-danger); }.feedback.success { color: var(--cr-status-success); }.emptyState { margin: 0; padding: 12px 0; color: var(--cr-text-muted); font-size: 14px; }
.modalBackdrop { position: fixed; z-index: 40; inset: 0; display: grid; place-items: center; padding: 16px; background: color-mix(in srgb, var(--cr-text-primary) 46%, transparent); }.confirmDialog { width: min(560px, 100%); max-height: min(90dvh, 760px); overflow: auto; padding: 16px; border: 1px solid var(--cr-border-strong); border-radius: 8px; background: var(--cr-surface); }.confirmDialog h2 { margin: 0; font-size: 20px; }.confirmDialog > p { color: var(--cr-text-secondary); font-size: 14px; line-height: 1.5; }.confirmList { display: grid; gap: 8px; padding-left: 20px; font-size: 14px; }.dialogActions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
@media (max-width: 900px) { .contentGrid { grid-template-columns: 1fr; } }.filters { grid-template-columns: repeat(2, minmax(0, 1fr)); }
@media (max-width: 620px) { .pageContent { width: min(100% - 24px, 1280px); }.pageHeading, .sectionHeading { align-items: start; flex-direction: column; }.filters, .objectEditor { grid-template-columns: 1fr; }.objectEditor label:nth-child(2), .objectEditor label:nth-child(3) { grid-column: auto; }.requestRow > span, .objectCard header { align-items: start; flex-direction: column; }.dialogActions { display: grid; grid-template-columns: 1fr; }.dialogActions button { width: 100%; } }
</style>
